import {createHash} from 'node:crypto';

const short=text=>String(text||'').replace(/\s+/g,' ').trim().slice(0,320);
const sourceIdFor=doi=>`E_EPMC_${createHash('sha256').update(doi).digest('hex').slice(0,16).toUpperCase()}`;

export function createEuropePmcBundle(result){
 if(!result?.doi||!result.pmcid||!result.source_sha256||!Array.isArray(result.paragraphs)||!result.paragraphs.length)throw new Error('Europe PMC bundle requires DOI, PMCID, source hash, and extracted paragraphs.');
 const source_id=sourceIdFor(result.doi),entries=result.paragraphs.map((paragraph,index)=>({id:`${source_id}_P${String(index+1).padStart(4,'0')}`,label:`${result.title||result.doi} — ${paragraph.locator}`,source:`https://doi.org/${result.doi}`,uri:result.full_text_url,locator:paragraph.locator,excerpt:short(paragraph.content),source_sha256:result.source_sha256,verified:false,verification_status:'pending_human_review',note:'Machine-extracted Europe PMC JATS paragraph. Verify against the original article; open-access status does not establish permission to redistribute this text or reuse figures.'}));
 const markdown=[`# ${result.title||result.doi}`,'',`- DOI: https://doi.org/${result.doi}`,`- PMCID: ${result.pmcid}`,`- Authors: ${result.authors||'not supplied'}`,`- Journal: ${result.journal||'not supplied'}`,`- Year: ${result.publication_year||'not supplied'}`,`- Source SHA-256: ${result.source_sha256}`,'- Verification: pending human review','- Rights: needs human review','',...result.paragraphs.flatMap(paragraph=>[`## ${paragraph.locator}`,'',paragraph.content,''])].join('\n');
 const manifest={schema_version:'1.0.0',source_id,provider:'europepmc',doi:result.doi,pmcid:result.pmcid,title:result.title,authors:result.authors,journal:result.journal,publication_year:result.publication_year,open_access_reported_by_provider:true,license:result.license||null,retrieved_at:result.retrieved_at,metadata_url:result.metadata_url,full_text_url:result.full_text_url,metadata_sha256:result.metadata_sha256,source_file:'source.xml',source_sha256:result.source_sha256,bytes:result.bytes,paragraph_count:result.paragraphs.length,extraction_method:'JATS XML paragraph extraction',verification_status:'pending_human_review',reuse_rights:'needs_review',warnings:['Provider open-access metadata is not legal review; confirm the article-specific license and reuse terms.','Extracted text is unverified and should be checked against original article context.','This adapter covers Europe PMC records only; it does not resolve arbitrary publisher URLs or download PDFs.']};
 return{source_id,markdown,manifest,evidence:{entries}};
}
